// Garbage rows by lines cleared (index 0..4): plain, T-spin mini, full T-spin.
export function attackNone(lines: i32): i32 {
  if (lines == 0) return 0;
  if (lines == 1) return 0;
  if (lines == 2) return 1;
  if (lines == 3) return 2;
  if (lines == 4) return 4;
  return 4;
}

export function attackTSpinMini(lines: i32): i32 {
  if (lines == 0) return 0;
  if (lines == 1) return 0;
  if (lines == 2) return 1;
  if (lines == 3) return 2;
  if (lines == 4) return 4;
  return 4;
}

export function attackTSpin(lines: i32): i32 {
  if (lines == 0) return 0;
  if (lines == 1) return 2;
  if (lines == 2) return 4;
  if (lines == 3) return 6;
  if (lines == 4) return 6;
  return 6;
}
